        gentoo: { walk: 22, slide: 0, swim: 70, porp: true, hop: 9, toboggan: false, rock: 25, amp: 0.09, stroke: 2.18 },
        macaroni: { walk: 18, slide: 0, swim: 60, porp: true, hop: 7, toboggan: false, rock: 9, amp: 0.05, hops: true, stroke: 2.29 },
