                const tr = H.tracks[H.tracks.length - 1]; if (onLand(H.x, H.y) && (!tr.length || Math.hypot(tr[tr.length - 1].x - H.x, tr[tr.length - 1].y - H.y) > 2.2)) tr.push({ x: H.x, y: H.y, h: H.h, side: tr.length % 2 ? 1 : -1 });
