        ctx.fillStyle = '#2a2d31'; ctx.beginPath(); ctx.arc(0.3, -7.8, 0.8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#d9a64a'; ctx.beginPath(); ctx.moveTo(0, -8.3); ctx.lineTo(0.3, -11.4); ctx.lineTo(0.6, -8.3); ctx.closePath(); ctx.fill();
