                const fin = m.fin || 0, side = m.sd > 0 ? 'r' : 'l';
                for (const [kx, a] of [[1.3, 0.35], [1, 0.55], [0.7, 1]]) {
                    ctx.save(); ctx.beginPath(); ctx.ellipse(-m.sd * L * 0.02, -L * 0.15, L * 0.1 * kx, L * 0.26 * kx, 0, 0, Math.PI * 2); ctx.clip();
                    pose(null, a, 'b'); ctx.restore(); }
