        ctx.beginPath(); ctx.moveTo(-1.1, 0); ctx.quadraticCurveTo(-2.4, 3.2, -2.3, 6.2); ctx.quadraticCurveTo(-1.2, 7.4, 0, 6.9); ctx.quadraticCurveTo(1.2, 7.5, 2.3, 6.2); ctx.quadraticCurveTo(2.4, 3.2, 1.1, 0); ctx.closePath();
