        if (dive > 0) { ctx.save(); ctx.beginPath(); ctx.rect(-14, -16 + dive * 26, 28, 40); ctx.clip(); }
        const wid = Math.max(0.55, Math.abs(rc)) * (1 - lk * 0.15);
