            ctx.strokeStyle = 'rgba(214,180,90,0.6)'; ctx.lineWidth = 0.5; ctx.beginPath(); ctx.moveTo(-12, -0.2); ctx.bezierCurveTo(-5, -2.6, 4, 4, 12, 2); ctx.stroke();
